    "sourceSection": "كتاب الطهارة — باب يرفع الحدث وحكم الخبث, « فرع أتى الجنب بئرا قليلة الماء » et « فرع الغسل في الحياض قبل غسل الأذى » (t. 1, p. 76–77)",
